import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"3、【屯】 震下坎上","description":"橫渠易說 - 3、【屯】 震下坎上","frontmatter":{"title":"3、【屯】 震下坎上","description":"橫渠易說 - 3、【屯】 震下坎上"},"headers":[],"relativePath":"classics/hengqu/005.md","filePath":"classics/hengqu/005.md"}'),l={name:"classics/hengqu/005.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_3、【屯】-震下坎上" tabindex="-1">3、【屯】 震下坎上 <a class="header-anchor" href="#_3、【屯】-震下坎上" aria-label="Permalink to “3、【屯】 震下坎上”">​</a></h1><h3 id="彖曰-屯-剛柔始交而難生-動乎險中-大亨貞。雷雨之動滿盈-天造草昧-宜建侯而不寧。" tabindex="-1">彖曰：屯，剛柔始交而難生，動乎險中，大亨貞。雷雨之動滿盈，天造草昧，宜建侯而不寧。 <a class="header-anchor" href="#彖曰-屯-剛柔始交而難生-動乎險中-大亨貞。雷雨之動滿盈-天造草昧-宜建侯而不寧。" aria-label="Permalink to “彖曰：屯，剛柔始交而難生，動乎險中，大亨貞。雷雨之動滿盈，天造草昧，宜建侯而不寧。”">​</a></h3><p>往則失其居矣。</p><h3 id="象曰-雲雷屯-君子以經綸。" tabindex="-1">象曰：雲雷屯，君子以經綸。 <a class="header-anchor" href="#象曰-雲雷屯-君子以經綸。" aria-label="Permalink to “象曰：雲雷屯，君子以經綸。”">​</a></h3><p>雲雷皆是氣之聚處，屯，聚也。</p><h3 id="初九-磐桓-利居貞-利建侯。-象曰-雖磐桓-志行正也。以貴下賤-大得民也。" tabindex="-1">初九，磐桓，利居貞，利建侯。 象曰：雖磐桓，志行正也。以貴下賤，大得民也。 <a class="header-anchor" href="#初九-磐桓-利居貞-利建侯。-象曰-雖磐桓-志行正也。以貴下賤-大得民也。" aria-label="Permalink to “初九，磐桓，利居貞，利建侯。 象曰：雖磐桓，志行正也。以貴下賤，大得民也。”">​</a></h3><p>磐桓猶言柱石。磐，磐石也；桓，桓柱也；謂利建侯，如柱石在下不可以動，然志在行正也。</p><h3 id="六二-屯如邅如-乘馬班如-匪寇婚媾。女子貞不字-十年乃字。-象曰-六二之難-乘剛也。-十年乃字-反常也。" tabindex="-1">六二，屯如邅如，乘馬班如，匪寇婚媾。女子貞不字，十年乃字。 象曰：六二之難，乘剛也。“十年乃字”，反常也。 <a class="header-anchor" href="#六二-屯如邅如-乘馬班如-匪寇婚媾。女子貞不字-十年乃字。-象曰-六二之難-乘剛也。-十年乃字-反常也。" aria-label="Permalink to “六二，屯如邅如，乘馬班如，匪寇婚媾。女子貞不字，十年乃字。 象曰：六二之難，乘剛也。“十年乃字”，反常也。”">​</a></h3><p>班，布，不進之貌。</p><h3 id="六三-即鹿無虞-惟入於林中-君子幾不如舍-往吝。-象曰-即鹿無虞-以從禽也。君子舍之-往吝窮也。" tabindex="-1">六三，即鹿無虞，惟入於林中，君子幾不如舍，往吝。 象曰：“即鹿無虞”，以從禽也。君子舍之，往吝窮也。 <a class="header-anchor" href="#六三-即鹿無虞-惟入於林中-君子幾不如舍-往吝。-象曰-即鹿無虞-以從禽也。君子舍之-往吝窮也。" aria-label="Permalink to “六三，即鹿無虞，惟入於林中，君子幾不如舍，往吝。 象曰：“即鹿無虞”，以從禽也。君子舍之，往吝窮也。”">​</a></h3><p>處非其地，故曰“入於林中”。虞，防禁也。二以乘剛有寇，故五若可親；五屯其膏，故不若舍之。</p><h3 id="六四-乘馬班如-求婚媾-往吉-無不利。-象曰-求而往-明也。" tabindex="-1">六四，乘馬班如，求婚媾，往吉，無不利。 象曰：求而往，明也。 <a class="header-anchor" href="#六四-乘馬班如-求婚媾-往吉-無不利。-象曰-求而往-明也。" aria-label="Permalink to “六四，乘馬班如，求婚媾，往吉，無不利。 象曰：求而往，明也。”">​</a></h3><h3 id="九五-屯其膏-小貞吉-大貞兇。-象曰-屯其膏-施未光也。" tabindex="-1">九五，屯其膏，小貞吉，大貞兇。 象曰：“屯其膏”，施未光也。 <a class="header-anchor" href="#九五-屯其膏-小貞吉-大貞兇。-象曰-屯其膏-施未光也。" aria-label="Permalink to “九五，屯其膏，小貞吉，大貞兇。 象曰：“屯其膏”，施未光也。”">​</a></h3><h3 id="上六-乘馬班如-泣血漣如。-象曰-泣血漣如-何可長也" tabindex="-1">上六，乘馬班如，泣血漣如。 象曰：“泣血漣如”，何可長也! <a class="header-anchor" href="#上六-乘馬班如-泣血漣如。-象曰-泣血漣如-何可長也" aria-label="Permalink to “上六，乘馬班如，泣血漣如。 象曰：“泣血漣如”，何可長也!”">​</a></h3><p>待求而往。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
